begin;
create or replace function pg_temp.expect_error(p_sql text,p_message text) returns void language plpgsql as $$ begin execute p_sql; raise exception 'expected error %',p_message; exception when others then if sqlerrm='expected error '||p_message or position(p_message in sqlerrm)=0 then raise; end if; end $$;
do $$
declare a uuid:='71000000-0000-4000-8000-000000000001'; b uuid:='71000000-0000-4000-8000-000000000002'; c uuid:='71000000-0000-4000-8000-000000000003'; creator uuid:='71000000-0000-4000-8000-000000000010'; quiz uuid:='71000000-0000-4000-8000-000000000011'; target uuid; attempt uuid; pass uuid; job uuid; passport uuid; conversation uuid; message_id uuid; result jsonb; begin
 insert into public.app_users(id,privy_user_id,verified_email) values(a,'did:privy:social-a','social-a@example.test'),(b,'did:privy:social-b','social-b@example.test'),(c,'did:privy:social-c','social-c@example.test');
 insert into public.celebrities(id,slug,status,image_url,published_at,roles,primary_role) values(creator,'social-creator','published','/social.webp',now(),'{creator}','creator');
 insert into public.celebrity_localizations(celebrity_id,locale,name,summary,image_alt) values(creator,'ko','소셜','소개','소셜'),(creator,'en','Social','Summary','Social');
 insert into public.celebrity_quizzes(id,celebrity_id,version,status) values(quiz,creator,1,'draft');
 alter table public.fan_passports disable trigger fan_passports_validate_blockchain_job_link;
 foreach target in array array[a,b] loop
   attempt:=extensions.gen_random_uuid(); pass:=extensions.gen_random_uuid(); job:=extensions.gen_random_uuid(); passport:=extensions.gen_random_uuid();
   insert into public.quiz_attempts(id,app_user_id,celebrity_id,quiz_id,quiz_version,idempotency_key,status,score,submitted_at) values(attempt,target,creator,quiz,1,extensions.gen_random_uuid(),'passed',3,now());
   insert into public.quiz_passes(id,app_user_id,celebrity_id,winning_attempt_id) values(pass,target,creator,attempt);
   insert into public.blockchain_jobs(id,entity_type,entity_id,operation_key,payload) values(job,'passport',passport,'social-passport-'||passport::text,'{}');
   insert into public.fan_passports(id,app_user_id,celebrity_id,quiz_pass_id,blockchain_job_id) values(passport,target,creator,pass,job);
 end loop;
 alter table public.fan_passports enable trigger fan_passports_validate_blockchain_job_link;
 if public.read_owned_social_settings(a)<>jsonb_build_object('profileVisible',false,'favoriteSlugs','[]'::jsonb,'dmPolicy','friends') then raise exception 'privacy defaults must remain private'; end if;
 perform public.set_owned_social_settings(a,true,array['social-creator'],'requests');
 perform public.set_owned_social_settings(b,true,array['social-creator'],'requests');
 result:=public.read_social_fan_profile(a,b,'social-creator','ko');
 if result#>>'{profile,id}'<>b::text or result#>>'{favorite,fanXp}'<>'0' or jsonb_array_length(result->'commonFavorites')<>1 or result#>>'{profile,accountLevel,status}'<>'configured' or result#>>'{profile,accountLevel,xp}'<>'0' or jsonb_typeof(result->'activities')<>'array' then raise exception 'public profile/common favorite contract failed: %',result; end if;
 if result#>>'{capabilities,canRequestFriend}'<>'true' or public.read_social_fan_profile(c,b,'social-creator','ko')#>>'{capabilities,canRequestFriend}'<>'false' then raise exception 'friend eligibility must require the viewer fan passport'; end if;
 result:=public.read_owned_social_profile_link(a);
 if public.read_owned_social_profile_link(a)->>'token'<>result->>'token' then raise exception 'unexpired profile link rotated'; end if;
 perform public.resolve_social_profile_link(b,(result->>'token')::uuid,'social-creator','ko',null,null,null,12);
 if public.read_owned_social_friends(b,'ko')#>>'{exchanges,0,profileId}'<>a::text or jsonb_typeof(public.read_owned_social_friends(b,'ko')->'friendships')<>'array' then raise exception 'profile exchange record contract failed'; end if;
 if public.resolve_social_profile_link(b,(result->>'token')::uuid,'social-creator','ko')#>>'{profile,id}'<>a::text then raise exception 'four-argument profile link wrapper diverged'; end if;
 update public.social_profile_links set expires_at=now()-interval '1 second' where app_user_id=a;
 if public.read_owned_social_profile_link(a)->>'token'=result->>'token' then raise exception 'expired profile link did not rotate'; end if;
 result:=public.request_social_dm(a,b,'first hello','72000000-0000-4000-8000-000000000001'); conversation:=(result->>'id')::uuid;
 if result->>'status'<>'pending' or result->>'firstMessageId' is null or public.request_social_dm(a,b,'first hello','72000000-0000-4000-8000-000000000001')->>'replayed'<>'true' then raise exception 'dm request replay failed'; end if;
 if public.read_owned_social_request_status(a,'72000000-0000-4000-8000-000000000001')#>>'{operation}'<>'request_dm' or public.read_owned_social_request_status(a,'72000000-0000-4000-8000-000000000099')->>'state'<>'not_found' then raise exception 'request outcome lookup failed'; end if;
 perform pg_temp.expect_error(format('select public.request_social_dm(%L,%L,%L,%L)',a,c,'first hello','72000000-0000-4000-8000-000000000001'),'SOCIAL_IDEMPOTENCY_CONFLICT');
 result:=public.resolve_social_dm(b,conversation,'accept','72000000-0000-4000-8000-000000000002');
 if public.resolve_social_dm(b,conversation,'accept','72000000-0000-4000-8000-000000000002') is distinct from result then raise exception 'dm resolution replay failed'; end if;
 perform pg_temp.expect_error(format('select public.resolve_social_dm(%L,%L,%L,%L)',b,conversation,'reject','72000000-0000-4000-8000-000000000002'),'SOCIAL_IDEMPOTENCY_CONFLICT');
 result:=public.send_social_dm_message(a,conversation,'hello','72000000-0000-4000-8000-000000000003'); message_id:=(result->>'id')::uuid;
 if public.send_social_dm_message(a,conversation,'hello','72000000-0000-4000-8000-000000000003')->>'replayed'<>'true' then raise exception 'message replay failed'; end if;
 perform pg_temp.expect_error(format('select public.send_social_dm_message(%L,%L,%L,%L)',a,conversation,'changed','72000000-0000-4000-8000-000000000003'),'SOCIAL_IDEMPOTENCY_CONFLICT');
 if jsonb_array_length(public.read_social_dm_messages(b,conversation,null,null,50)->'messages')<>2 then raise exception 'recipient history missing'; end if;
 perform public.delete_owned_social_dm_message(a,message_id);
 if jsonb_array_length(public.read_social_dm_messages(a,conversation,null,null,50)->'messages')<>1 or jsonb_array_length(public.read_social_dm_messages(b,conversation,null,null,50)->'messages')<>2 then raise exception 'sender-only deletion violated'; end if;
 perform public.block_social_profile(b,a,'72000000-0000-4000-8000-000000000004');
 if public.read_social_fan_profile(b,a,'social-creator','ko') is not null then raise exception 'blocked public profile leaked'; end if;
 perform pg_temp.expect_error(format('select public.read_social_dm_messages(%L,%L,null,null,50)',a,conversation),'SOCIAL_BLOCKED');
 perform public.unblock_social_profile(b,a);
 if (select status from public.social_dm_conversations where id=conversation)<>'rejected' then raise exception 'unblock restored dm approval'; end if;
 perform pg_temp.expect_error(format('select public.request_social_dm(%L,%L,%L,%L)',a,b,'too soon','72000000-0000-4000-8000-000000000006'),'SOCIAL_RATE_LIMITED');
 perform pg_temp.expect_error(format('select public.send_social_dm_message(%L,%L,%L,%L)',a,conversation,'after unblock','72000000-0000-4000-8000-000000000005'),'SOCIAL_FORBIDDEN');
 insert into public.account_deletion_requests(app_user_id,provider_subject) values(a,'did:privy:social-a');
 update public.app_users set status='disabled' where id=a;
 if (select body from public.social_dm_messages where id=message_id)<>'[deleted]' or exists(select 1 from public.social_profile_settings where app_user_id=a) then raise exception 'account deletion did not scrub social PII'; end if;
 if has_table_privilege('service_role','public.social_dm_messages','SELECT') or has_function_privilege('authenticated','public.send_social_dm_message(uuid,uuid,text,uuid)','EXECUTE') then raise exception 'RLS/service RPC boundary failed'; end if;
end $$;
rollback;
